import { Cause, Effect, Exit, Ref } from "effect"

export interface SitemapState {
  readonly status: "idle" | "building" | "ready" | "failed"
  readonly urls: ReadonlyArray<string>
  readonly lastError: string | undefined
}

export const initialSitemapState: SitemapState = {
  status: "idle",
  urls: [],
  lastError: undefined
}

export const refreshSitemap = (
  state: Ref.Ref<SitemapState>,
  build: Effect.Effect<ReadonlyArray<string>, Error>
): Effect.Effect<boolean> =>
  Effect.gen(function*() {
    yield* Ref.update(state, (current) => ({
      ...current,
      status: "building",
      lastError: undefined
    }))

    const exit = yield* build.pipe(Effect.exit)
    if (Exit.isSuccess(exit)) {
      yield* Ref.set(state, {
        status: "ready",
        urls: exit.value,
        lastError: undefined
      })
      return true
    }

    yield* Ref.update(state, (current) => ({
      ...current,
      status: "failed",
      lastError: Cause.pretty(exit.cause)
    }))
    return false
  })
